const fs = require('fs');
const JSDOM = require('/home/prem/monkeytype/monkeytype/node_modules/.pnpm/jsdom@27.4.0_supports-color@10.2.2/node_modules/jsdom').JSDOM;
const html = fs.readFileSync('app/index.html', 'utf8');
const dom = new JSDOM(html, { runScripts: 'dangerously', resources: 'usable' });
const win = dom.window;
global.window = win;
global.document = win.document;
require('./app/js/config.js');
require('./app/js/views/home.js');

const bgA = win.document.getElementById('bgA');
const bgB = win.document.getElementById('bgB');

const home = win.HomeViewController;
home.init();

// Rapidly focus 5 different cards in 100ms
const cards = [1, 2, 3, 4, 5].map(i => {
  const c = win.CardFactory.createPosterCard({ id: i, title: 'Movie ' + i, backdropUrl: 'http://cdn/bg' + i + '.jpg' }, 'shelf-1', i);
  return c;
});

let setsCount = 0;
const origSrcDesc = Object.getOwnPropertyDescriptor(win.HTMLImageElement.prototype, 'src');
Object.defineProperty(bgA, 'src', {
  set(v) { setsCount++; this.setAttribute('src', v); },
  get() { return this.getAttribute('src'); }
});
Object.defineProperty(bgB, 'src', {
  set(v) { setsCount++; this.setAttribute('src', v); },
  get() { return this.getAttribute('src'); }
});

for (const c of cards) {
  home.handleElementFocus(c);
}

console.log('Immediate src sets after 5 rapid focus events:', setsCount);

setTimeout(() => {
  console.log('After 350ms src sets:', setsCount);
  console.log('Active bg src:', bgB.getAttribute('src') || bgA.getAttribute('src'));
}, 350);
